import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)

def get_pkgs(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw['topLevelPackages']:
                key = (name, fw['framework'], pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

bp = get_pkgs(b)
ap = get_pkgs(a)

changes = []
for k in sorted(set(list(bp.keys()) + list(ap.keys()))):
    bv = bp.get(k, 'N/A')
    av = ap.get(k, 'N/A')
    if bv != av:
        changes.append((k[0], k[1], k[2], bv, av))

if changes:
    print('CHANGES:')
    for c in changes:
        print(f'  {c[0]} | {c[1]} | {c[2]} | {c[3]} -> {c[4]}')
else:
    print('No version changes detected (besides alignment to highest)')
print(f'\nTotal packages baseline: {len(bp)}, after: {len(ap)}')
"

